formal_property.sva:
// 假设数组宽度由参数 RdataDepth 决定；断言不允许越界访问
assert property (@(posedge clk_i) disable iff (!rst_ni) 
  (|sram_req_rdata.mask) |-> (sram_req_rdata.woffset < RdataDepth));

