formal_property.sva:
// 假设参数 MAGIC_DATA, MAGIC_ADDR 已定义；opcode 编码：PutFullData=0, Get=1
// 期望：任何合法请求（a_valid）且地址/数据匹配魔术值时，下一个周期 bug 注入应该触发
// 当前实现只在 PutFullData 下触发，本断言将暴露其他 opcode 时未触发的缺口
assert property (@(posedge clk_i) disable iff (!rst_ni)
   (tl_h_i.a_valid && tl_h_i.a_opcode != 3'd0 && tl_h_i.a_data == `MAGIC_DATA && tl_h_i.a_address == `MAGIC_ADDR) |=> tlul_bug_001_fire);

formal.sva:
// 假设参数 MAGIC_DATA, MAGIC_ADDR 已定义；opcode 编码：PutFullData=0, Get=1
// 期望：任何合法请求（a_valid）且地址/数据匹配魔术值时，下一个周期 bug 注入应该触发
// 当前实现只在 PutFullData 下触发，本断言将暴露其他 opcode 时未触发的缺口
assert property (@(posedge clk_i) disable iff (!rst_ni)
   (tl_h_i.a_valid && tl_h_i.a_opcode != 3'd0 && tl_h_i.a_data == `MAGIC_DATA && tl_h_i.a_address == `MAGIC_ADDR) |=> tlul_bug_001_fire);

formal_property.sva:
// 检查 state_d 非法编码时 state_q 不应进入未定义状态
let legal_state = (state_d == StActive) || (state_d == StError) || (state_d == StErrorOutstanding);
assert property (@(posedge clk_i) disable iff (!rst_ni)
   !legal_state |-> ##1 (state_q inside {StActive, StError, StErrorOutstanding})
) else $error("Illegal state_d caused undefined state_q");

